# We will read each batch and generate src/data/collegesData.json
records = []

def add_r(code, name, place, dist, coed, ctype, bcode, bname, cutoffs_str, aff):
    parts = cutoffs_str.strip().split()
    keys = [
        "OC_BOYS", "OC_GIRLS", "BC_A_BOYS", "BC_A_GIRLS", "BC_B_BOYS", "BC_B_GIRLS",
        "BC_C_BOYS", "BC_C_GIRLS", "BC_D_BOYS", "BC_D_GIRLS", "BC_E_BOYS", "BC_E_GIRLS",
        "SC_I_BOYS", "SC_I_GIRLS", "SC_II_BOYS", "SC_II_GIRLS", "SC_III_BOYS", "SC_III_GIRLS",
        "ST_BOYS", "ST_GIRLS", "EWS_BOYS", "EWS_GIRLS"
    ]
    c_map = {}
    for i, k in enumerate(keys):
        val = parts[i] if i < len(parts) else "NA"
        c_map[k] = None if val == "NA" else int(val)
    
    records.append({
        "id": f"{code}-{bcode}",
        "instCode": code,
        "instituteName": name,
        "place": place,
        "distCode": dist,
        "coEducation": coed,
        "collegeType": ctype,
        "branchCode": bcode,
        "branchName": bname,
        "affiliatedTo": aff,
        "cutoffs": c_map
    })

